    benefits: [{ title: "Datenschutz im Blick", text: "Ein eigener Bereich für den Dienst" }, { title: "Mehrere Sprachen", text: "Eine erweiterbare Oberfläche" }, { title: "Einfach zu nutzen", text: "Klare Schritte für jede Woche" }, { title: "Hilfe und Support", text: "Kontaktwege werden hier veröffentlicht" }, { title: "Kostenlose Preview", text: "Ein gemeinsamer Starttermin" }],
    showcaseEyebrow: "Ein Blick in den Arbeitsbereich", showcaseTitle: "Die Arbeit an einem Ort bündeln", showcaseLead: "Von Kindern und Klassen bis Anwesenheit, Mitarbeitenden, Begleitung, Mitteilungen und Berichten – in einem Arbeitsbereich.", demoLabel: "Produktdemo ausschließlich mit synthetischen Daten", demoItems: ["Kinder", "Klassen", "Anwesenheit", "Begleitung"], showcasePoints: ["Kinder und Klassen verwalten", "Anwesenheit erfassen und prüfen", "Begleitung und Mitteilungen organisieren", "Berichte für die Teams ansehen"],
    featuresEyebrow: "Werkzeuge für den Dienst", featuresTitle: "Werkzeuge für Sonntagsschul-Teams", featuresLead: "Aktuelle Funktionen sind klar gekennzeichnet. Mehrgemeinde-Funktionen befinden sich noch in Entwicklung.", available: "Im aktuellen Arbeitsbereich verfügbar", planned: "In Entwicklung",
    features: [{ title: "Mitarbeitende und Klassen", text: "Mitarbeitendendaten und Klassen im aktuellen Gemeindebereich organisieren.", status: "available" }, { title: "Kinder und Begleitung", text: "Kinderprofile, Fürsorge-Notizen und pädagogische Begleitung.", status: "available" }, { title: "Anwesenheit", text: "Anwesenheit erfassen sowie Termine und Verlauf einsehen.", status: "available" }, { title: "Mitteilungen und Berichte", text: "Gemeindenachrichten teilen und Zusammenfassungen sowie Analysen ansehen.", status: "available" }, { title: "Gemeindeverzeichnis und Anfragen", text: "Eine Gemeinde finden und eine Anfrage zur Prüfung senden.", status: "planned" }, { title: "Mehrere Gemeinden und Sprachen", text: "Getrennte Bereiche und echte RTL/LTR-Oberflächen.", status: "planned" }],
    howEyebrow: "Der Weg zur Plattform", howTitle: "Ein klarer Weg für Gemeinden und Mitarbeitende", howLead: "Die Registrierung und der Beitritt für mehrere Gemeinden sind in Arbeit. Eine Anfrage allein gewährt niemals Zugriff.", steps: [{ title: "Gemeinde registrieren", text: "Eine autorisierte Person übermittelt Gemeinde- und erste Administratorangaben." }, { title: "Arbeitsbereich einrichten", text: "Nach erfolgreicher Bereitstellung erhält der Administrator einen privaten Einladungscode." }, { title: "Beitritt anfragen", text: "Mitarbeitende finden die Gemeinde oder geben den Code ein und senden eine Anfrage." }, { title: "Administrator prüft", text: "Der Administrator nimmt die Anfrage an oder lehnt sie ab, bevor Zugriff erteilt wird." }],
    directoryEyebrow: "Gemeinden entdecken", directoryTitle: "Gemeinde finden oder neuen Bereich starten", directoryLead: "Das Verzeichnis zeigt nur freigegebene öffentliche Informationen. Codes und Mitgliederdaten bleiben privat.", directoryAction: "Gemeinde finden", joinAction: "Gemeinde beitreten", directoryNote: "Verzeichnis und Beitrittsanfragen sind noch nicht verfügbar. Vor Aktivierung entsteht keine Mitgliedschaft.",
    previewEyebrow: "Globale Preview", previewTitle: "Während der Preview kostenlos starten", previewBody: "Der kostenlose Zweijahreszeitraum beginnt an einem gemeinsamen offiziellen Plattformstart, nicht mit der Registrierung jeder Gemeinde.", previewRule: "Während der Preview sind weder Kreditkarte noch Zahlungen oder Checkout erforderlich. Der offizielle Termin wird nach Bestätigung in den Plattformeinstellungen veröffentlicht.", previewAction: "Gemeinde registrieren", faqEyebrow: "Klare Antworten", faqTitle: "Häufige Fragen", questions: [{ question: "Was ist Sonntagsschule?", answer: "Ein digitaler Arbeitsbereich für Kinder, Klassen, Mitarbeitende, Anwesenheit, Begleitung, Mitteilungen und Berichte. Einige Mehrgemeinde-Funktionen sind noch in Entwicklung." }, { question: "Wer kann eine Gemeinde registrieren?", answer: "Eine autorisierte Vertretung der Gemeinde. Sichere Registrierung und eine eigene Datenbank werden derzeit implementiert; diese Seite bestätigt noch keine abgeschlossene Registrierung." }, { question: "Wie kann jemand einer Gemeinde beitreten?", answer: "Die Person wählt eine Gemeinde im Verzeichnis oder verwendet einen privaten Code und sendet eine Anfrage. Beides gewährt nicht automatisch Zugriff." }, { question: "Warum ist eine Freigabe erforderlich?", answer: "Damit die Gemeinde die Anfrage prüfen und unbefugten Zugriff verhindern kann. Ein Administrator muss Mitgliedschaft und Rechte freigeben." }, { question: "Wie funktioniert die Preview?", answer: "Zwei gemeinsame kostenlose Jahre ab dem offiziellen Plattformstart, ohne Karte und Zahlung. Das offizielle Datum wurde noch nicht veröffentlicht." }, { question: "Wie werden Kinderdaten geschützt?", answer: "Kinderdaten erscheinen weder im Verzeichnis noch in der Produktdemo. Hier werden keine echten Datensätze gezeigt; die endgültige Datenschutzerklärung wird noch geprüft." }],
    contactEyebrow: "Kontakt", contactTitle: "Wir freuen uns über Rückmeldungen", contactText: "Der offizielle Kontaktweg wird vorbereitet.", contactStatus: "Eine verifizierte Support-Adresse oder Telefonnummer ist noch nicht veröffentlicht.", footerText: "Ein digitaler Arbeitsbereich für die Sonntagsschule.", privacy: "Datenschutz", terms: "Nutzungsbedingungen", demo: "Demo", dashboardTitle: "Sonntagsschul-Arbeitsbereich", dashboardCaption: "Dienstübersicht", sample: "Beispieldaten",
