    howEyebrow: "Como participar", howTitle: "Um caminho claro para igrejas e servos", howLead: "O cadastro e a entrada em várias igrejas estão em desenvolvimento. Um pedido não concede acesso por si só.", steps: [{ title: "Cadastre uma igreja", text: "Um representante autorizado envia os dados da igreja e do primeiro administrador." }, { title: "Prepare o espaço", text: "Após a provisão, o administrador recebe um código privado para compartilhar." }, { title: "Peça para participar", text: "O servo encontra a igreja ou informa o código e envia um pedido." }, { title: "Análise do administrador", text: "O administrador aprova ou recusa o pedido antes de qualquer acesso." }],
